        for w, c in doc.items():
            label_docs[row['answer']][w] += c
    centroids = {}
    for lab, counter in label_docs.items():
        vec = {w: c * idf.get(w, 1.0) for w, c in counter.items()}
        norm = math.sqrt(sum(v * v for v in vec.values()))
        centroids[lab] = ({w: v / max(1e-12, norm) for w, v in vec.items()}, norm)
