    q_terms = Counter(q_tokens)
    q_bi = bigrams(q_tokens)
    q_chars = chargrams(query)
    docs = [Counter(tok(row['question'])) for row in memory]
    n = max(1, len(docs))
    df = Counter(w for doc in docs for w in doc)
    idf = {w: math.log(1 + (n - df[w] + 0.5) / (df[w] + 0.5)) for w in df}
    avg = sum(sum(d.values()) for d in docs) / n
