    label_docs = {lab: Counter() for lab in labels}
    for row, doc in zip(memory, docs):
        for w, c in doc.items():
            label_docs[row['answer']][w] += c
    centroids = {}
    for lab, counter in label_docs.items():
        vec = {w: c * idf.get(w, 1.0) for w, c in counter.items()}
        norm = math.sqrt(sum(v * v for v in vec.values()))
        centroids[lab] = ({w: v / max(1e-12, norm) for w, v in vec.items()}, norm)
    qv = {w: c * idf.get(w, 1.0) for w, c in q_terms.items()}
    qn = math.sqrt(sum(v * v for v in qv.values()))
    label_sim = {lab: sum(qv.get(w, 0) * v for w, v in centroids[lab][0].items()) / max(1e-12, qn) for lab in labels}
