        return [{"id": r["id"], "score": 1.0 / (i + 1)} for i, r in enumerate(memory)]
    df = Counter(w for d in docs for w in set(d))
    def idf(w):
        return math.log((n + 1) / (df.get(w, 0) + 1)) + 1
    avg = sum(len(d) for d in docs) / n
    qcount = Counter(q)
    qbi = Counter(zip(q, q[1:]))
    qchar = trigrams(q)
    lex = []
    for d in docs:
        dc = Counter(d)
        size = len(d)
        bm = 0.0
        for w, f in qcount.items():
            if dc.get(w):
                bm += idf(w) * dc[w] * 2.2 / (dc[w] + 1.2 * (0.25 + 0.75 * size / max(1.0, avg)))
