    return math.sqrt(sum(v * v for v in c.values())) or 1.0

def cos(a, b):
    if not a or not b:
        return 0.0
    if len(b) < len(a):
        a, b = b, a
    return sum(v * b.get(k, 0.0) for k, v in a.items()) / (vnorm(a) * vnorm(b))

